app.get('/assets/member-extra.js',(q,r)=>r.type('text/javascript; charset=utf-8').send("var oldMemberLoad=load;\nload=async function(s){await oldMemberLoad(s);if(s==='pay')D.payInfo=await api('payment-info')};\nvar payerPhone='';\nfunction destinationNumber(){return D.payInfo[way==='Orange Money'?'orange_number':way==='MTN Money'?'mtn_number':'wave_number']||'À confirmer auprès de l’administrateur'}\npayNow=async function(){var pn=(document.getElementById('payerPhone')||{}).value||payerPhone;if(pn.replace(/\\D/g,'').length<8)return toast('Saisissez le numéro Mobile Money utilisé pour le dépôt');if(!gid)return toast('Aucun groupe disponible');if(!confirm('Réseau : '+way+'\\nVotre numéro de dépôt : '+pn+'\\nNuméro de réception Nafa Finance : '+destinationNumber()+'\\nConfirmer la demande ? Le paiement ne sera pas confirmé automatiquement par l’opérateur.'))return;try{await api('pay',{group_id:gid,amount:amount,method:way,payer_phone:pn});payerPhone=pn;await go('tx');toast('Demande enregistrée · en attente de validation')}catch(e){toast(e.message)}};\nV.pay=function(){if(!gid&&D.groups[0])gid=D.groups[0].id;var f=D.quote?D.quote.total:amount;return hdr('Cotiser')+'<div class=\"scr\"><div class=\"card\"><label>Groupe</label><select onchange=\"gid=+this.value\">'+rows(D.groups,function(g){return '<option value=\"'+g.id+'\"'+(g.id==gid?' selected':'')+'>'+esc(g.name)+' · '+money(g.amount)+'</option>'})+'</select><label>Montant de la cotisation (FCFA)</label><input type=\"number\" min=\"100\" value=\"'+amount+'\" oninput=\"amount=parseInt(this.value)||0;refreshQuote()\"><small id=\"fees\" style=\"color:var(--mut)\">'+(D.quote?(D.quote.first_contribution?'Première cotisation : '+money(D.quote.admin_fee)+' administration + '+money(D.quote.referral_fee)+' parrain (si code valide).':'Cotisation suivante : aucune commission.'):'Calcul des frais…')+'</small><h3 style=\"margin-top:12px\">Total à payer : <span id=\"tot\" style=\"color:#b8860b\">'+money(f)+'</span></h3><label>Réseau de paiement</label><div class=\"pay\">'+['Orange Money','MTN Money','Wave'].map(function(w){return '<button class=\"'+(w==way?'on':'')+'\" onclick=\"way=\\''+w+'\\';draw()\">'+w+'</button>'}).join('')+'</div><div style=\"background:#f5f7fc;border-radius:12px;padding:12px;margin-top:12px;color:var(--ink)\"><b>Numéro Nafa Finance à créditer</b><div style=\"font-size:18px;font-weight:800;margin:5px 0\">'+esc(destinationNumber())+'</div><small>Vérifiez ce numéro avant d’effectuer le dépôt.</small></div><label style=\"display:block;margin-top:12px\">Votre numéro '+esc(way)+' utilisé pour le dépôt</label><input id=\"payerPhone\" inputmode=\"tel\" placeholder=\"Ex. 07 00 00 00 00\" value=\"'+esc(payerPhone)+'\" oninput=\"payerPhone=this.value\"><button class=\"btn\" onclick=\"payNow()\">Envoyer ma demande de cotisation</button><small style=\"color:var(--mut)\">La demande reste en attente jusqu’à vérification. La confirmation automatique de l’opérateur n’est pas encore active.</small></div></div>'+mnav('pay')};\ndraw();"));
app.get('/assets/admin-extra.js',(q,r)=>r.type('text/javascript; charset=utf-8').send("var oldAdminLoad=load;\nload=async function(s){await oldAdminLoad(s);if(s==='chart')D.an=await api('admin/analytics');if(s==='grp'){D.an=await api('admin/analytics');D.groups=await api('groups')}if(s==='set')D.settings=await api('admin/settings')};\nanav=function(c){return nav([['adm','🏠','Accueil'],['mem','👥','Membres'],['grp','🗂️','Groupes'],['val','✅','Paiements'],['set','⚙️','Réglages']],c)};\nasync function saveSettings(){try{await api('admin/settings',{orange_number:v('orange_number'),mtn_number:v('mtn_number'),wave_number:v('wave_number')});D.settings=await api('admin/settings');draw();toast('Paramètres enregistrés')}catch(e){toast(e.message)}}\nasync function saveGroup(id){var old=id?D.groups.find(g=>g.id==id):null;var name=prompt('Nom du groupe :',old?old.name:'');if(name===null)return;var a=prompt('Montant de cotisation en FCFA :',old?old.amount:'500');if(a===null)return;try{await api(id?'admin/groups/'+id:'admin/groups',{name:name,amount:parseInt(a,10)});await go('grp',1);toast(id?'Groupe modifié':'Groupe créé')}catch(e){toast(e.message)}}\nasync function memberDetail(id){try{var d=await api('admin/members/'+id),m=d.member;var t='FICHE DU MEMBRE\\nNom : '+m.name+'\\nTéléphone : '+m.phone+'\\nDate de naissance : '+(m.birth||'Non renseignée')+'\\nSexe : '+(m.sex||'Non renseigné')+'\\nInscription : '+dt(m.created)+'\\nGroupe(s) : '+m.groups+'\\nCode de parrainage : '+(m.referral_code||'—')+'\\nCotisations validées : '+m.validated_payments+'\\nTotal validé : '+money(m.total_paid)+'\\n\\nHISTORIQUE DES COTISATIONS\\n';t+=d.payments.length?d.payments.map(function(p){return dt(p.created)+' · '+p.group_name+' · '+p.method+' · dépôt depuis '+(p.payer_phone||'—')+' · '+money(p.amount)+' · '+p.status}).join('\\n'):'Aucune cotisation';alert(t)}catch(e){toast(e.message)}}\nV.adm=function(){var s=D.st;return '<div class=\"scr\"><div style=\"display:flex;font-weight:800;font-size:19px;margin-bottom:12px\"><span style=\"flex:1\">Espace Administrateur</span><button onclick=\"logout()\" style=\"background:none;border:0;color:#fff;font-size:20px\">⎋</button></div><div class=\"stats\"><div class=\"stat\" style=\"background:#2b6fd6\">Membres<b>'+(s.members||0)+'</b></div><div class=\"stat\" style=\"background:var(--green)\">Groupes<b>'+(s.groups||0)+'</b></div><div class=\"stat\" style=\"background:#e08a1e\">Cotisations validées<b>'+money(s.total||0)+'</b></div><div class=\"stat\" style=\"background:var(--red)\">Paiements en attente<b>'+(s.pending||0)+'</b></div></div><div class=\"grid\" style=\"margin-top:14px\">'+[['chart','📈','Graphique cotisations'],['grp','🗂️','Inscrits par groupes'],['mem','👥','Fiches des membres'],['val','✅','Valider paiements'],['not','🔔','Notifications'],['set','⚙️','Paramètres']].map(function(t){return '<button class=\"tile\" onclick=\"go(\\''+t[0]+'\\')\"><i>'+t[1]+'</i>'+t[2]+'</button>'}).join('')+'</div></div>'+anav('adm')};\nV.chart=function(){var a=D.an.daily||[],max=Math.max(1,...a.map(function(x){return Number(x.amount)||0}));return hdr('Graphique des cotisations')+'<div class=\"scr\"><div class=\"card\"><h3>Cotisations validées — 30 jours</h3>'+(a.length?a.map(function(x){return '<div style=\"margin:12px 0\"><div style=\"display:flex;justify-content:space-between;font-size:12px\"><b>'+esc(x.label)+'</b><span>'+money(x.amount)+' · '+x.count+' paiement(s)</span></div><div style=\"height:12px;background:#e8ecf6;border-radius:8px;overflow:hidden\"><div style=\"height:12px;width:'+Math.max(2,Number(x.amount)/max*100)+'%;background:#2e9e5b;border-radius:8px\"></div></div></div>'}).join(''):'<p>Aucune cotisation validée sur les 30 derniers jours.</p>')+'</div><div class=\"card\"><h3>Totaux par groupe</h3>'+rows(D.an.groups||[],function(g){return '<div class=\"row\" style=\"cursor:default\"><div class=\"t\"><b>'+esc(g.name)+'</b><small>'+g.members+' membre(s)</small></div><b>'+money(g.total)+'</b></div>'})+'</div></div>'+anav('')};\nV.mem=function(){return hdr('Liste des membres')+'<div class=\"scr\"><div class=\"card\"><p>Appuyez sur un membre pour consulter sa fiche et son historique.</p>'+(D.mem.length?rows(D.mem,function(m){return '<div class=\"row\" onclick=\"memberDetail('+m.id+')\"><span>👤</span><div class=\"t\"><b>'+esc(m.name)+'</b><small>'+esc(m.phone)+' · '+esc(m.groups)+' · inscrit le '+dt(m.created)+'</small><small>'+m.validated_payments+' cotisation(s) validée(s) · '+money(m.total_paid)+'</small></div></div>'}):'<p>Aucun membre inscrit.</p>')+'</div></div>'+anav('mem')};\nV.grp=function(){return hdr('Groupes et inscrits')+'<div class=\"scr\"><button class=\"btn\" onclick=\"saveGroup(0)\">＋ Créer un groupe</button><div class=\"card\">'+rows(D.groups,function(g){return '<div class=\"row\" style=\"cursor:default\"><div class=\"t\"><b>'+esc(g.name)+'</b><small>'+g.members+' membre(s) · Cotisation '+money(g.amount)+'</small></div><div class=\"a\"><button onclick=\"saveGroup('+g.id+')\">Modifier</button></div></div>'})+'</div><div class=\"card\"><h3>Répartition des membres</h3>'+rows(D.an.groups||[],function(g){return '<div class=\"row\" style=\"cursor:default\"><div class=\"t\"><b>'+esc(g.name)+'</b><small>'+g.members+' inscrit(s)</small></div><span class=\"pill\">'+money(g.total)+'</span></div>'})+'</div></div>'+anav('grp')};\nV.val=function(){return hdr('Valider les paiements')+'<div class=\"scr\"><div class=\"card\"><h3>En attente ('+D.pay.length+')</h3>'+(D.pay.length?rows(D.pay,function(p){return '<div class=\"row\" style=\"cursor:default;align-items:flex-start\"><div class=\"t\"><b>'+esc(p.name)+'</b><small>Téléphone membre : '+esc(p.member_phone)+'</small><small>'+esc(p.method)+' · dépôt depuis : '+esc(p.payer_phone||'non indiqué')+'</small><small>'+esc(p.group_name)+' · '+money(p.amount)+' · '+dt(p.created)+'</small><small>Frais : '+money(p.fee||0)+' (admin '+money(p.admin_fee||0)+', parrain '+money(p.referral_fee||0)+')</small></div><div class=\"a\"><button onclick=\"dec('+p.id+',\\'validate\\')\">Valider</button><button class=\"r\" onclick=\"dec('+p.id+',\\'refuse\\')\">Refuser</button></div></div>'}):'<p>Aucun paiement en attente.</p>')+'</div></div>'+anav('val')};\nV.set=function(){return hdr('Paramètres')+'<div class=\"scr\"><div class=\"card\"><h3>Numéros de réception Nafa Finance</h3><p>Les membres verront ces numéros après avoir choisi le réseau de paiement.</p><label>Orange Money</label><input id=\"orange_number\" inputmode=\"tel\" value=\"'+esc(D.settings.orange_number||'')+'\" placeholder=\"Numéro Orange Money\"><label>MTN Money</label><input id=\"mtn_number\" inputmode=\"tel\" value=\"'+esc(D.settings.mtn_number||'')+'\" placeholder=\"Numéro MTN Money\"><label>Wave</label><input id=\"wave_number\" inputmode=\"tel\" value=\"'+esc(D.settings.wave_number||'')+'\" placeholder=\"Numéro Wave\"><button class=\"btn\" onclick=\"saveSettings()\">Enregistrer</button></div><div class=\"card\"><b>À savoir</b><p>Cette fonction affiche les numéros et enregistre la demande. Elle ne confirme pas automatiquement les dépôts auprès des opérateurs.</p></div></div>'+anav('set')};\ndraw();"));
app.get('/',(q,r)=>r.redirect('/member/'));
app.get(['/assets/nafa-logo.png','/assets/nafa-icon-192.png'],(q,r)=>r.type('image/png').send(PNG));
app.get(Object.keys(FILES),(q,r)=>{const p=q.path.replace(/^\/(member|admin)\/?$/,'/$1/');const f=FILES[p];if(!f)return r.sendStatus(404);r.type(f[0]).send(f[1])});
init().then(()=>app.listen(process.env.PORT||3000,()=>console.log('Nafa Finance prêt'))).catch(e=>{console.error(e);process.exit(1)});
